UPDATE sites
   SET followup_sent_at = $2
 WHERE id = $1
   AND handed_over_at IS NOT NULL
   AND handed_over_at <= $3
   AND live_link_expires_at > $2
   AND transfer_confirmed_at IS NULL
   AND followup_sent_at IS NULL
RETURNING handed_over_at, live_link_expires_at
// then, on ErrNoRows only, one SELECT that classifies:
//   confirmed -> ErrFollowupSuppressed (order matters: it is the button working)
//   sent      -> ErrFollowupAlreadySent
//   expired   -> ErrFollowupWindowClosed
//   else      -> ErrFollowupNotDue

func ConfirmTokenURL(host, token string) (string, error) {
	if host == "" { return "", fmt.Errorf("…nowhere to point") }
	if strings.Contains(host, "/") { return "", fmt.Errorf("…must be a bare host") }
	return (&url.URL{Scheme:"https", Host:host, Path:"/c/"+token}).String(), nil
}

